"""Random values, plus ones built from a chosen number of set bits so both
parities show up on purpose rather than by luck."""


def generate(rng, count):
    builders = (_anything, _chosen_bit_count, _one_bit)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, value, description=""):
    return {"name": name, "stdin": "%X\n" % value, "description": description}


def _anything(rng, index):
    return _case("a random value #%d" % index, rng.randrange(0, 2 ** 32))


def _chosen_bit_count(rng, index):
    n = rng.randint(0, 32)
    positions = rng.sample(range(32), n)
    value = 0
    for bit in positions:
        value |= 1 << bit
    parity = "even" if n % 2 == 0 else "odd"
    return _case("exactly %d bit(s) set #%d" % (n, index), value,
                 "%d set bits is %s." % (n, parity))


def _one_bit(rng, index):
    bit = rng.randrange(32)
    return _case("one bit alone #%d" % index, 1 << bit,
                 "A single set bit is always odd parity.")
